// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { z } from "zod";
import { APP_API_HEADER, APP_API_VERSION } from "../packages/app-backend/src/index.js";
import { createGodseyeClient } from "../packages/sdk/src/index.js";
import { appTestIdentity, type BackendFixture, backendFixture } from "./backend-fixture.js";

/** Cookie jar emulates browser-owned application cookies without granting owner authority. */
function sdkFor(fixture: BackendFixture, chunkBytes = 3) {
  const jar = new Map<string, string>();
  const requests: Request[] = [];
  const client = createGodseyeClient({
    baseUrl: fixture.baseUrl,
    scope: fixture.scope,
    chunkBytes,
    reconnectMs: 10,
    fetch: async (input, init) => {
      const request = new Request(input, init);
      request.headers.set("origin", fixture.baseUrl);
      request.headers.set("cookie", [...jar].map(([name, value]) => `${name}=${value}`).join("; "));
      requests.push(request.clone());
      const response = await fixture.runtime.app.fetch(request);
      for (const cookie of response.headers.getSetCookie()) {
        const pair = cookie.split(";")[0] ?? "";
        const separator = pair.indexOf("=");
        if (separator > 0) jar.set(pair.slice(0, separator), pair.slice(separator + 1));
      }
      return response;
    },
  });
  return { client, requests };
}

describe("TypeScript application SDK composed with actual first-party runtime", () => {
  let fixture: BackendFixture;
  beforeEach(async () => {
    fixture = await backendFixture({
      limits: { streamPollMs: 10 },
      routes: (registry) => {
        registry.get("/typed-fixture", z.object({ value: z.number() }).strict(), async () => ({
          value: 42,
        }));
        registry.post(
          "/echo",
          z.object({ message: z.string().max(100) }).strict(),
          z.object({ message: z.string(), userId: z.string() }).strict(),
          async ({ input, user }) => ({ message: input.message, userId: user.id }),
        );
      },
    });
  });
  afterEach(async () => fixture.close());

  it("T-AC-60 signs up, reads session, uploads multiple chunks and downloads private UTF-8 bytes", async () => {
    const { client, requests } = sdkFor(fixture);
    const user = await client.auth.signUp(appTestIdentity);
    expect((await client.auth.session())?.user.id).toBe(user.user.id);
    const bytes = new TextEncoder().encode("SDK héllo 🛰️");
    const file = await client.files.upload({
      name: "sdk.txt",
      contentType: "text/plain",
      data: bytes,
    });
    expect(file).toMatchObject({ status: "committed", size: bytes.length, offset: bytes.length });
    expect((await client.files.list()).files.map((item) => item.id)).toEqual([file.id]);
    expect(await (await client.files.download(file.id)).text()).toBe("SDK héllo 🛰️");
    expect(requests.filter((request) => request.method === "PUT").length).toBeGreaterThan(1);
    for (const request of requests) {
      expect(request.headers.get("X-Godseye-Project")).toBe(fixture.scope.projectId);
      expect(request.headers.get("X-Godseye-Environment")).toBe(fixture.scope.environmentId);
      expect(request.headers.get(APP_API_HEADER)).toBe(APP_API_VERSION);
      expect(request.credentials).toBe("include");
    }
    await client.auth.signOut();
    expect(await client.auth.session()).toBeNull();
    await expect(client.files.list()).rejects.toMatchObject({
      code: "UNAUTHENTICATED",
      status: 401,
    });
  });

  it("T-AC-60 manages exact download grant and rejects it after SDK revocation", async () => {
    const { client } = sdkFor(fixture);
    await client.auth.signUp(appTestIdentity);
    const file = await client.files.upload({
      name: "grant.txt",
      contentType: "text/plain",
      data: new Blob(["grant bytes"]),
    });
    const grant = await client.files.createGrant(file.id, file.revision, 1000);
    expect(await (await client.files.downloadGrant(grant.id)).text()).toBe("grant bytes");
    expect(await client.files.revokeGrant(file.id, grant.id)).toEqual({ revoked: true });
    await expect(client.files.downloadGrant(grant.id)).rejects.toMatchObject({ status: 404 });
  });

  it("T-AC-60 replays a completed upload under the original idempotency key after a lost completion acknowledgement", async () => {
    const { client } = sdkFor(fixture);
    await client.auth.signUp(appTestIdentity);
    const input = {
      name: "replay.txt",
      contentType: "text/plain",
      data: new TextEncoder().encode("same completed bytes"),
    };
    const options = { idempotencyKey: randomUUID() };
    const first = await client.files.upload(input, options);
    const replay = await client.files.upload(input, options);
    expect(replay).toEqual(first);
    expect((await client.files.list()).files).toHaveLength(1);
  });

  it("T-AC-60 consumes scoped real SSE events and releases the stream when iteration stops", async () => {
    const { client } = sdkFor(fixture);
    const user = await client.auth.signUp(appTestIdentity);
    const published = await fixture.runtime.publishEvent({
      userId: user.user.id,
      type: "document.updated",
      payload: { value: 1 },
      idempotencyKey: randomUUID(),
    });
    const abort = new AbortController();
    const subscription = client.events.subscribe({ signal: abort.signal, reconnect: false });
    const first = await subscription.next();
    expect(first.value).toMatchObject({ kind: "event", event: published });
    await subscription.return(undefined);
    abort.abort();
    expect(fixture.runtime.state.streams.size).toBe(0);
  });

  it("T-AC-60 exposes versioned typed custom route responses and runtime errors", async () => {
    const { client } = sdkFor(fixture);
    await expect(
      client.request("/typed-fixture", {}, z.object({ value: z.number() }).strict()),
    ).rejects.toMatchObject({ status: 401 });
    await client.auth.signUp(appTestIdentity);
    expect(
      await client.request("/typed-fixture", {}, z.object({ value: z.number() }).strict()),
    ).toEqual({ value: 42 });
    await expect(
      client.request("/absent", {}, z.object({ value: z.number() })),
    ).rejects.toMatchObject({ code: "NOT_FOUND", status: 404 });
  });

  it("T-AC-60 never follows a custom route path outside the application API", async () => {
    const { client, requests } = sdkFor(fixture);
    for (const path of ["/../../api/v1/projects", "/..\\owner", "/%2e%2e/%2e%2e/api/v1/projects"])
      await expect(
        Promise.resolve().then(() => client.request(path, {}, z.unknown())),
      ).rejects.toThrow();
    expect(requests).toHaveLength(0);
  });

  it("T-AC-60 preserves custom mutation idempotency, exact user scope and input validation", async () => {
    const { client } = sdkFor(fixture);
    const user = await client.auth.signUp(appTestIdentity);
    const schema = z.object({ message: z.string(), userId: z.string() }).strict();
    const input = {
      method: "POST" as const,
      body: { message: "first" },
      idempotencyKey: randomUUID(),
    };
    const first = await client.request("/echo", input, schema);
    expect(first).toEqual({ message: "first", userId: user.user.id });
    expect(await client.request("/echo", input, schema)).toEqual(first);
    await expect(
      client.request("/echo", { ...input, body: { message: "changed" } }, schema),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT", status: 409 });
    await expect(
      client.request("/echo", { method: "POST", body: { message: "missing key" } }, schema),
    ).rejects.toMatchObject({ status: 422 });
    await expect(
      client.request(
        "/echo",
        { ...input, idempotencyKey: randomUUID(), body: { message: "forged", role: "owner" } },
        schema,
      ),
    ).rejects.toMatchObject({ status: 422 });
  });
});
